import { ViewTransition } from 'react'

/**
 * Wraps page content with directional slide animations keyed to navigation
 * transition types. Place this in each `page.tsx` (not the layout) so that
 * `enter`/`exit` fire on route changes.
 *
 * - `nav-forward` (list -> detail): old page slides left, new page slides in
 *   from the right.
 * - `nav-back` (detail -> list): old page slides right, new page slides in
 *   from the left.
 * - Untyped navigations (browser back/forward, refresh, Suspense reveals)
 *   resolve to `default: 'none'` and produce no directional slide, so they
 *   don't compete with shared-element morphs or Suspense reveals.
 */
export function DirectionalTransition({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <ViewTransition
      enter={{
        'nav-forward': 'nav-forward',
        'nav-back': 'nav-back',
        default: 'none',
      }}
      exit={{
        'nav-forward': 'nav-forward',
        'nav-back': 'nav-back',
        default: 'none',
      }}
      default="none"
    >
      {children}
    </ViewTransition>
  )
}

